<?php require __DIR__.'/_layout_start.php'; ?><div class="toolbar"><div><h1>Campus - Eventi</h1><p class="muted"><?=($audience??'')==='cat'?'Eventi riservati ai CAT':(($audience??'')==='public'?'Eventi aperti':'Tutti gli eventi')?></p></div><a class="btnlink" href="/admin/campus/events/form">Nuovo evento</a></div><div class="quick-list" style="grid-template-columns:repeat(3,minmax(0,180px));margin-bottom:18px"><a href="/admin/campus/events"><span>Tutti</span></a><a href="/admin/campus/events?audience=public"><span>Eventi aperti</span></a><a href="/admin/campus/events?audience=cat"><span>Eventi CAT</span></a></div><div class="table-wrap"><table><thead><tr><th>Evento</th><th>Tipologia</th><th>Data</th><th>Iscrizioni</th><th>Stato</th><th>Azioni</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><strong><?=htmlspecialchars($e['title'],ENT_QUOTES,'UTF-8')?></strong><?=!empty($e['category'])?'<br><span class="muted">'.htmlspecialchars($e['category'],ENT_QUOTES,'UTF-8').'</span>':''?></td><td><span class="badge"><?=$e['audience']==='cat'?'CAT':'Aperto'?></span></td><td><?=htmlspecialchars(date('d/m/Y H:i',strtotime((string)$e['starts_at'])),ENT_QUOTES,'UTF-8')?></td><td><?=(int)$e['registrations']?></td><td><?=(int)$e['cancelled']?'Annullato':((int)$e['published']?'Pubblicato':'Bozza')?></td><td><a href="/admin/campus/events/form?id=<?=(int)$e['id']?>">Modifica</a><form method="post" action="/admin/campus/events/duplicate" style="display:inline;margin-left:8px"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf,ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id" value="<?=(int)$e['id']?>"><button type="submit" class="link-button">Duplica</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/_layout_end.php'; ?>
